import { test } from '@playwright/test';
import * as ui from '../support/ui';
test('dbg', async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg = await ui.userPage(browser, 'uma', sheet);
  pg.on('console', m => console.log('CONSOLE', m.text()));
  pg.on('response', r => { if (r.url().includes('/api/')) console.log('RESP', r.request().method(), r.url(), r.status()); });
  const a = ui.must(await ui.addPerson(pg, { name: 'Ada', grade: 'A' }));
  await ui.editOpen(pg, a);
  await pg.getByTestId('person-form-terms').fill('x');
  await pg.getByTestId('person-form-submit').click();
  for (let i = 0; i < 10; i++) { await pg.waitForTimeout(300); console.log(i, pg.url(), await pg.getByTestId('person-form-error').count(), await pg.getByTestId('person-form-name').inputValue()); }
});
EOF
